import{_ as n,l as i,o as a,c as l,v as e,p as s,x as r,d as p,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"Kolmogorov 复杂度","description":"","frontmatter":{"title":"Kolmogorov 复杂度","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kolmogorov-complexity.md","filePath":"cs/kolmogorov-complexity.md","lastUpdated":1789023840000}'),h={name:"cs/kolmogorov-complexity.md"};function x(c,o,K,_,f,g){const t=i("Mermaid");return a(),l("div",null,[o[1]||(o[1]=e('<h1 id="kolmogorov-复杂度" tabindex="-1">Kolmogorov 复杂度 <a class="header-anchor" href="#kolmogorov-复杂度" aria-label="Permalink to &quot;Kolmogorov 复杂度&quot;">​</a></h1><div class="epigraph"><p>串 $x$ 的复杂度是打印 $x$ 然后停机的最短程序长度；几乎所有串都接近最大，而 $K$ 本身不可计算。</p><footer>—— 据 Kolmogorov, 1965；Chaitin；Li and Vitányi, An Introduction to Kolmogorov Complexity 整理</footer></div><p>上一课<a href="/cs/recursion-theorem">递归定理</a>让程序可以谈自身。缺口是给串一个<strong>描述长度</strong>，不依赖概率。<a href="/cs/entropy-bits">熵</a>是分布上的平均；这里单根串、最坏描述。本课钉 \\(K(x)\\)、不可计算、与随机串。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>固定通用 TM（前缀自由或普通，差一个加性常数）。\\(K(x)=\\min\\{|p|:\\ U(p)=x\\}\\)。显然 \\(K(x)\\le |x|+O(1)\\)（硬编码）。不可计算：若 \\(K\\) 可计算，可枚举「\\(K(x)\\ge n\\) 的最短 \\(x\\)」，其描述「第 \\(n\\) 个不可压缩串」长度 \\(O(\\log n)\\)，矛盾——Berry 悖论的可计算版，合法性靠递归定理。</p><p>随机串： \\(K(x)\\ge |x|-c\\)。多数串如此（计数：短程序太少）。这与「通过统计检验」不同，但是 Martin-Löf 随机在前缀 \\(K\\) 下可对齐，本课点名。</p><h3 id="不是-shannon-熵" tabindex="-1">不是 Shannon 熵 <a class="header-anchor" href="#不是-shannon-熵" aria-label="Permalink to &quot;不是 Shannon 熵&quot;">​</a></h3><p>熵要 \\(p(x)\\)。均匀分布下典型串的 \\(K\\) 约 \\(n\\)，与熵同阶；换分布，熵低的源仍有个别高 \\(K\\) 的串。不要把压缩软件的输出长度写成 \\(K\\)——那是上界，且相对具体格式。</p><p><span class="marginnote">Kolmogorov 1965；Solomonoff、Chaitin 同期。Li–Vitányi 是标准书。前缀复杂度 \\(K\\) 让 Kraft 不等式可用；课堂常先讲普通 \\(C(x)\\)，差 \\(O(\\log n)\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>证明不可计算用「最短不可压缩」自指。应用：不可压缩串没有短循环、不能有太长的 \\(0\\) 段（否则可描述）。条件 \\(K(x\\mid y)\\) 点名，不展开链规则全文。</p>',11)),(a(),s(m,null,{default:r(()=>[d(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E4%B8%B2%20x%22%5D%20--%3E%20P%5B%22%E6%9C%80%E7%9F%AD%E7%A8%8B%E5%BA%8F%20p%22%5D%0A%20%20P%20--%3E%20K%5B%22K(x)%3D%7Cp%7C%22%5D%0A%20%20K%20--%3E%20UNC%5B%22K%20%E4%B8%8D%E5%8F%AF%E8%AE%A1%E7%AE%97%22%5D%0A%20%20K%20--%3E%20RAND%5B%22K%E2%89%88%7Cx%7C%EF%BC%9A%E9%9A%8F%E6%9C%BA%E4%B8%B2%22%5D%0A"})]),fallback:r(()=>[...o[0]||(o[0]=[p(" Loading... ",-1)])]),_:1})),o[2]||(o[2]=e('<p><a href="/cs/source-coding-theorem">信源编码</a>那里平均码长对 Shannon。这里单串、最坏、相对通用机。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(K\\) 对可计算变换几乎不变（加常数或对数）。故「是否随机」不依赖编程语言，只要通用。不可判定性：集合 \\(\\{x:K(x)\\ge |x|/2\\}\\) 不可判定。这比停机更「量」：每个串都有一个数，只是算不出。</p><p>不要用 \\(K\\) 当文件压缩的目标函数去优化——不可计算。</p><p>条件复杂度 \\(K(x\\mid y)\\) 是已知 \\(y\\) 时打印 \\(x\\) 的最短程序。对称性 \\(K(x,y)\\approx K(x)+K(y\\mid x)\\) 差对数项。不可压缩串通过几乎所有可计算统计检验，这是 Martin-Löf 随机的桥，本课不把测度论写完。压缩器给出的长度永远是 \\(K\\) 的上界。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Martin-Löf 的测度论定义，不引入算法信息的缺一性引理全文。不把大模型的「压缩即智能」写成定理。后课默认：\\(K(x)\\) 是最短程序长，不可计算；随机串是不可压缩串。下一课换模型：λ 演算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(K(x)\\) = 输出 \\(x\\) 的最短程序长；相对通用机差常数。</li><li>\\(K\\) 不可计算；多数串不可压缩。</li><li>与 Shannon 熵分工：单串 vs 分布。</li><li>出处：Kolmogorov, 1965；Li and Vitányi。</li></ul>',9))])}const E=n(h,[["render",x]]);export{A as __pageData,E as default};
